from dataclasses import dataclass
from typing import Any, Dict, Optional


@dataclass
class OrderResult:
    order_id: Any
    total: float
    user_id: Any


def _validate_order(order: Optional[Dict[str, Any]]) -> bool:
    if order is None:
        return False
    if order.get("status") != "pending":
        return False
    items = order.get("items")
    if not items:
        return False
    if order.get("user_id") is None:
        return False
    for item in items:
        if item.get("price") is None or item.get("quantity") is None:
            return False
    return True


def process_order(order: Optional[Dict[str, Any]]) -> Optional[OrderResult]:
    if not _validate_order(order):
        return None
    total = sum(item["price"] * item["quantity"] for item in order["items"])
    return OrderResult(order_id=order["id"], total=total, user_id=order["user_id"])
